"""Check the integration against schema generated by the installed Codex binary."""

import json
import shutil
import subprocess
import tempfile
import unittest
from pathlib import Path

from slack_debug.config import CODEX_VERSION


class InstalledProtocolTests(unittest.TestCase):
    @unittest.skipUnless(shutil.which("codex"), "Codex CLI not installed")
    def test_installed_schema_contract(self):
        version = subprocess.run(["codex", "--version"], capture_output=True, text=True, check=True)
        self.assertEqual(version.stdout.strip(), "codex-cli " + CODEX_VERSION)
        with tempfile.TemporaryDirectory() as directory:
            subprocess.run(
                ["codex", "app-server", "generate-json-schema", "--out", directory],
                capture_output=True,
                check=True,
            )
            root = Path(directory)
            for name, definition in (
                ("CommandExecution", "CommandExecutionApprovalDecision"),
                ("FileChange", "FileChangeApprovalDecision"),
            ):
                response = json.loads((root / f"{name}RequestApprovalResponse.json").read_text())
                values = {
                    v
                    for option in response["definitions"][definition]["oneOf"]
                    for v in option.get("enum", [])
                }
                self.assertTrue({"accept", "decline"} <= values)
            start = json.loads((root / "v2/ThreadStartParams.json").read_text())
            self.assertTrue(
                {
                    "developerInstructions",
                    "ephemeral",
                    "approvalPolicy",
                    "approvalsReviewer",
                    "sandbox",
                }
                <= start["properties"].keys()
            )
            turn = json.loads((root / "v2/TurnStartParams.json").read_text())
            self.assertTrue({"threadId", "input"} <= turn["properties"].keys())


if __name__ == "__main__":
    unittest.main()
